                //
                // Actually, it's KiB, MiB,
                // GiB and TiB since you are
                // dividing by 1024.
                //
                // If you divided by 1000
                // it would be without the i.
                //
                //
                // Devator
                // May 16, 2013 at 19:41
                //
                // # C # R # N # R # S # T # N # :: # L # I # G # H # T
                //
                // This is my impetus 
                // to include the above 
                // links to additional 
                // material from 
                // wikipedia into 
                // this source code. 
                //
                //
                // 5
                //
                // Friday, July 5, 2024 @ 0131 hrs.
                if($SI_output){

                    // SI :: metric prefix
                    $units = array('bytes', 'KB', 'MB', 'GB', 'TB', 'PB', 'EB', 'ZB', 'YB');
                    $units_power = 1000;

                }else{

                    // IEC :: ISO 80000 or IEC 80000
                    $units = array('bytes', 'KiB', 'MiB', 'GiB', 'TiB', 'PiB', 'EiB', 'ZiB', 'YiB');
                    $units_power = 1024;

                }

                $bytes = max($bytes, 0);
                $pow = floor(($bytes ? log($bytes) : 0) / log($units_power));
                $pow = min($pow, count($units) - 1);

                $bytes /= pow($units_power, $pow);

                $tmp_number = round($bytes, $precision);
                $tmp_number = $this->number_format_keep_precision($tmp_number);

                return $tmp_number . ' ' . $units[$pow];

            }

